_actionError(errorName, errorParams, serverErrorMsg) {
  if (!serverErrorMsg) {
    this._logger.error(`Got an error; name=${errorName}`);
  } else {
    this._logger.error(
      `Got an error; name=${errorName}. The server said: ${serverErrorMsg}`
    );
  }
  if (errorName == "pop3PasswordFailed") {
    return;
  }

  this._actionDone(Cr.NS_ERROR_FAILURE);

  let msgWindow = this._msgWindow;
  if (!msgWindow) {
    // If there's a message window on the URI, use that.
    // (The getter for `msgWindow` may throw).
    try {
      msgWindow = this.runningUri?.msgWindow;
    } catch {}
  }
  if (!msgWindow) {
    return;
  }
